1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "hybrid/v_regfile_xfer.hpp"
12	
13	#include <algorithm>
14	#include <array>
15	#include <cstdint>
16	#include <span>
17	
18	namespace hybrid
19	{
20	
21	class StateDrain
22	{
23	public:
24	  using RD = ResumeDriver;
25	
26	  explicit StateDrain(DmiBus& bus)
27	      : bus_{bus}
28	  {}
29	
30	  // F16: stash the warmup-window snapshot (mcycle, minstret captured K
31	  // retires after vsim entry). Both drain() and drain_with_passthrough()
32	  // copy these into the returned state. Zero when MeasureStartSnapshot
33	  // never fired (K=0 or workload exited inside the warmup window).
34	  void set_warmup_snapshot(uint64_t mcycle, uint64_t minstret)
35	  {
36	    warmup_mcycle_   = mcycle;
37	    warmup_minstret_ = minstret;
38	  }
39	
40	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
41	  // drain_with_passthrough when the QEMU 1 snapshot is available.
42	  auto drain() -> hybrid_state_v1
43	  {
44	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
45	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
46	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
47	                   "StateDrain halt");
48	
49	    hybrid_state_v1 state{};
50	    state.magic   = HYBRID_STATE_MAGIC;
51	    state.version = HYBRID_STATE_VERSION;
52	    state.flags   = HYBRID_FLAG_RV64;
53	    state.priv    = 3;
54	
55	    for (uint16_t i = 1; i < 32; ++i)
56	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
57	
58	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
59	    state.mcycle_at_measure_start   = warmup_mcycle_;
60	    state.minstret_at_measure_start = warmup_minstret_;
61	    return state;
62	  }
63	
64	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
65	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
66	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
67	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
68	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
69	  // and vreg remain pass-through (read-only / too large for DM).
70	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
71	  // contribution would otherwise be discarded as the passthrough preserves
72	  // QEMU1's pre-handoff value.
73	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
74	  {
75	    auto state       = input;
76	    const auto fresh = drain();
77	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
78	              std::begin(state.gpr) + 1);
79	    state.pc = fresh.pc;
80	
81	    if (input.flags & HYBRID_FLAG_FP) {
82	      for (uint16_t i = 0; i < 32; ++i)
83	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
84	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
85	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
86	    }
87	
88	    if (input.flags & HYBRID_FLAG_V) {
89	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
90	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
91	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
92	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
93	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
94	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
95	    }
96	
97	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
98	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
99	
100	    // V data regfile: dump v0..v31 to the shared scratch region via the
101	    // Program Buffer LAST -- after every architectural read above -- so the
102	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
103	    // cannot corrupt the values already captured. The simulator's
104	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
105	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
106	    if (input.flags & HYBRID_FLAG_V)
107	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, input.vlenb,
108	                      /*load=*/false);
109	
110	    state.mcycle_at_measure_start   = warmup_mcycle_;
111	    state.minstret_at_measure_start = warmup_minstret_;
112	    return state;
113	  }
114	
115	  // cosim_roi F1: checkpoint drain. Same capture as drain_with_passthrough,
116	  // but the hart must keep running afterwards. The exit drain may clobber
117	  // freely (the run ends there); a checkpoint must undo the dump sweep's
118	  // clobbers -- vtype/vl/vstart and the x5/x6/x7 scratch -- from the freshly
119	  // drained values, then resume. DPC is untouched, so the hart continues
120	  // exactly where the halt landed.
121	  auto drain_checkpoint(const hybrid_state_v1& input) -> hybrid_state_v1
122	  {
123	    const auto state = drain_with_passthrough(input);
124	
125	    if (input.flags & HYBRID_FLAG_V) {
126	      // vtype+vl atomically via vsetvl (direct vtype write sets vill; vl is
127	      // read-only), staged in x5/x6 like the ResumeDriver Tier-B restore.
128	      write_register_abstract(bus_, regno_gpr(5), state.vl);
129	      write_register_abstract(bus_, regno_gpr(6), state.vtype);
130	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
131	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
132	      // vstart AFTER vsetvl (vsetvl zeroes it), via PB csrrw staged in x7 --
133	      // still scratch until the GPR rewrite below.
134	      write_register_abstract(bus_, regno_gpr(7), state.vstart);
135	      const std::array<uint32_t, 1> pb_vstart = {
136	        encode_csrrw(0, RD::kCsrVstart, 7) };
137	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vstart});
138	      // Scratch GPRs back to the drained architectural values.
139	      write_register_abstract(bus_, regno_gpr(5), state.gpr[5]);
140	      write_register_abstract(bus_, regno_gpr(6), state.gpr[6]);
141	      write_register_abstract(bus_, regno_gpr(7), state.gpr[7]);
142	    }
143	
144	    bus_.write(RD::kDmcontrol,
145	               RD::kDmcontrolDmactive | RD::kDmcontrolResumereq);
146	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllresumeack,
147	                   "StateDrain checkpoint resume");
148	    return state;
149	  }
150	
151	private:
152	  DmiBus& bus_;
153	  uint64_t warmup_mcycle_   = 0;  // F16: zero when warmup boundary never fired
154	  uint64_t warmup_minstret_ = 0;
155	};
156	
157	}  // namespace hybrid
158

