193	  // Used for CSRs whose abstract-access support may be implementation
194	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
195	  // remaining writes.
196	  void write_csr_tolerant(uint16_t csr, uint64_t value)
197	  {
