203	  // is rejected until the bits are W1C-cleared. We tolerate per-register
204	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
205	  // error before resuming so the hart isn't left in a stuck state.
206	  // B17: record the last observed non-zero cmderr and a clear count so a
207	  // partially-broken restore is observable via the public accessors
208	  // instead of silently swallowed.
209	  void clear_cmderr_if_set()
210	  {
211	    const auto status = bus_.read(kAbstractcs);
212	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
213	    if (code != 0u) {
