215	      ++cmderr_clear_count_;
216	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
217	    }
218	  }
219	
220	  DmiBus& bus_;
221	  uint32_t last_observed_cmderr_ = 0;
222	  uint64_t cmderr_clear_count_   = 0;
