225	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
226	  // at least one abstract write tripped a sticky cmderr the restore
227	  // tolerated by clearing. cmderr_clear_count() is the total number of
228	  // such clears across all calls into clear_cmderr_if_set() this run.
229	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
230	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
231	};
