233	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
234	// via an Abstract Command. Halts-and-reads contract: caller must have the
235	// hart in the halted state. Shared by StateDrain (drain at exit), and by
236	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
237	// goes sticky after the command, the helper clears it and reports 0
238	// rather than blocking the caller -- a missing CSR mirrors as zero
239	// instead of corrupting the adjacent field.
240	inline auto read_register_64(DmiBus& bus, uint16_t regno,
241	                             const char* poll_label = "read_register_64")
242	  -> uint64_t
243	{
244	  using RD = ResumeDriver;
245	  bus.write(RD::kCommand,
246	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
247	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
248	  const auto status = bus.read(RD::kAbstractcs);
249	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
250	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
251	    return 0u;
252	  }
253	  const uint64_t lo = bus.read(RD::kData0);
254	  const uint64_t hi = bus.read(RD::kData1);
255	  return lo | (hi << 32);
256	}
