138	// haltreq propagates), and the two states only compare equal when both
139	// sides sample the SAME architectural point. If vsim's pc is never reached
140	// (a real control-flow divergence), the oracle never drains and QEMU runs
141	// to completion -- the caller sees exit != 200.
142	static uint64_t exit_pc_arg;
143	static int      exit_pc_mode;
