173	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
174	{
175	    for (guint i = 0; i < regs->len; i++) {
176	        qemu_plugin_reg_descriptor *rd =
177	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
178	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
179	            return rd->handle;
