237	static uint64_t read_reg64(struct qemu_plugin_register *h)
238	{
239	    if (!h) return 0;
240	    g_autoptr(GByteArray) buf = g_byte_array_new();
241	    int sz = qemu_plugin_read_register(h, buf);
242	    if (sz <= 0) return 0;
243	    uint64_t v = 0;
244	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
245	    return v;
246	}
