248	// Reads up to `dst_max` bytes from a register handle. Returns the byte
249	// count written (0 on failure or NULL handle). Used for vector regs whose
250	// width = vlenb bytes.
251	static size_t read_reg_bytes(struct qemu_plugin_register *h,
252	                             uint8_t *dst, size_t dst_max)
253	{
254	    if (!h || dst_max == 0) return 0;
255	    g_autoptr(GByteArray) buf = g_byte_array_new();
256	    int sz = qemu_plugin_read_register(h, buf);
257	    if (sz <= 0) return 0;
258	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
259	    memcpy(dst, buf->data, n);
260	    return n;
261	}
262	
263	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
264	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
265	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
266	// collide even under aggressive PID reuse (B13). The tmp lives in the
267	// same directory as `path` so the rename is intra-filesystem.
268	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
269	{
270	    char tmp[PATH_MAX];
271	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
272	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
273	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
274	        return -1;
275	    }
276	    int fd = g_mkstemp(tmp);
277	    if (fd < 0) {
278	        perror("hybrid_handoff: g_mkstemp");
279	        return -1;
280	    }
281	    // g_mkstemp creates the file 0600; no further chmod needed.
282	    ssize_t want = (ssize_t) sizeof(*s);
283	    ssize_t got = write(fd, s, sizeof(*s));
284	    if (got != want) {
285	        perror("hybrid_handoff: write");
286	        close(fd);
287	        unlink(tmp);
288	        return -1;
289	    }
290	    fsync(fd);
291	    close(fd);
292	    if (rename(tmp, path) != 0) {
293	        perror("hybrid_handoff: rename");
294	        unlink(tmp);
295	        return -1;
296	    }
297	    return 0;
298	}
299	
300	// Drain CPU state to `path`. pc is computed by the caller (from a
301	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
302	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
303	// minstret in the state file (used by drain_at_exit mode to record a
304	// plugin-counted retired-insn total). Does NOT call exit -- caller
305	// decides exit(200) (normal trigger) vs _exit(200) (inside atexit chain).
306	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
307	                                uint64_t minstret_override, const char *path)
308	{
309	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
310	    resolve_handles(v);
311	    struct hybrid_state_v1 s = {0};
312	    s.magic   = HYBRID_STATE_MAGIC;
313	    s.version = HYBRID_STATE_VERSION;
314	    s.flags   = HYBRID_FLAG_RV64;
315	    s.hart_id = vcpu_idx;
316	    s.priv    = 3;
317	    s.pc      = pc;
318	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
319	
320	    // Floating-point: only set FP flag if at least one handle was bound,
321	    // i.e. QEMU advertised the FPU feature (D extension).
322	    int has_fp = 0;
323	    for (int i = 0; i < 32; i++) {
324	        s.fpr[i] = read_reg64(v->fpr[i]);
325	        if (v->fpr[i]) has_fp = 1;
326	    }
327	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
328	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
329	
330	    s.mstatus  = read_reg64(v->mstatus);
331	    s.mepc     = read_reg64(v->mepc);
332	    s.mtvec    = read_reg64(v->mtvec);
333	    s.mcause   = read_reg64(v->mcause);
334	    s.mtval    = read_reg64(v->mtval);
335	    s.mscratch = read_reg64(v->mscratch);
336	    s.medeleg  = read_reg64(v->medeleg);
337	    s.mideleg  = read_reg64(v->mideleg);
338	    s.mip      = read_reg64(v->mip);
339	    s.mie      = read_reg64(v->mie);
340	    s.mcycle   = read_reg64(v->mcycle);
341	    s.minstret = minstret_override ? minstret_override
342	                                   : read_reg64(v->minstret);
343	    s.satp     = read_reg64(v->satp);
344	
345	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
346	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
347	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
348	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
349	
350	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
351	    // bounds the per-register byte count copied into vreg[]. The policy
352	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
353	    // handle truthiness so we don't conflate "stub missing vlenb" with
354	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
355	    s.vstart = read_reg64(v->vstart);
356	    s.vxsat  = read_reg64(v->vxsat);
357	    s.vxrm   = read_reg64(v->vxrm);
358	    s.vcsr   = read_reg64(v->vcsr);
359	    s.vtype  = read_reg64(v->vtype);
360	    s.vl     = read_reg64(v->vl);
361	    s.vlenb  = read_reg64(v->vlenb);
362	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
363	                       || v->vtype || v->vl);
364	    if (!has_other_v) {
365	        for (int i = 0; i < 32; i++)
366	            if (v->vreg[i]) { has_other_v = 1; break; }
367	    }
368	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
369	        v->vlenb != NULL, has_other_v, s.vlenb);
370	    if (vpol == HYBRID_V_DRAIN_ABORT) {
371	        if (v->vlenb == NULL)
372	            fprintf(stderr,
373	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
374	                    "vlenb; refusing to drain partial V state\n");
375	        else
376	            fprintf(stderr,
377	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
378	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
379	                    "truncate V registers\n",
380	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
381	                    8 * HYBRID_VLEN_BYTES_MAX);
382	        exit(2);
383	    }
384	    if (vpol == HYBRID_V_DRAIN_OK) {
385	        s.flags |= HYBRID_FLAG_V;
386	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
387	         * full live register fits the wire-format slot -- no clamp (L11). */
388	        for (int i = 0; i < 32; i++)
389	            (void) read_reg_bytes(v->vreg[i],
390	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
391	                                  (size_t) s.vlenb);
392	    }
393	
394	    if (write_state_atomic(&s, path) != 0) {
395	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
396	        exit(2);
397	    }
398	    fprintf(stderr,
399	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
400	            path, s.pc);
401	}
402	
403	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
404	// as the vsim resume point, and exit 200.
405	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
406	{
407	    // F14: suppress the atexit drain path now that we have a real trigger.
408	    drained_already = 1;
409	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
410	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
411	    // Distinguishes drain from workload completion (0) so the orchestrator
412	    // can decide the next spawn.
413	    exit(200);
414	}
415	
416	// Marker sites. The marker is an architectural NOP, so the pre-execution
417	// state equals the post-retire state and the window resumes AFTER it
418	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
419	// the exec callback can lag the actual current insn when V instructions
420	// retire just before the trigger -- TCG defers PC writes for performance).
421	static void on_handoff(unsigned int vcpu_idx, void *udata)
422	{
423	    const HandoffSite *site = (const HandoffSite *) udata;
424	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
425	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
426	}
427	
428	// pc/icount/slice boundary sites. Exec callbacks fire BEFORE the insn
429	// executes, and the boundary insn is real user code (unlike a marker NOP):
430	// the drained state must resume AT the boundary so the insn executes inside
431	// the vsim window rather than on neither leg. (Skipping it corrupts the
432	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
433	// set and the first vector op of the window faults.)
434	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
435	{
436	    const HandoffSite *site = (const HandoffSite *) udata;
437	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
438	    handoff_drain(vcpu_idx, site->vaddr);
439	}
440	
441	// F14: per-insn tick. Increments a global counter every retired insn so the
442	// drain-at-exit path can report a true retired-insn total (independent of
443	// QEMU's PMU semantics).
444	static void on_count_tick(unsigned int vcpu_idx, void *udata)
445	{
446	    (void) vcpu_idx;
447	    (void) udata;
448	    atexit_insn_count++;
449	}
450	
451	// F14: atexit drain. Fires when QEMU exits naturally (no ROI trigger). The
452	// record is a CONTEXT-FREE count, not an architectural drain: depending on
453	// the guest's exit path this callback runs on the vCPU thread (semihosting
454	// EXIT) or on QEMU's main loop thread (vplat/SimControl shutdown request),
455	// and on the main thread there is no vCPU context -- any
456	// qemu_plugin_read_register aborts QEMU (api.c asserts current_cpu). The
457	// only consumer (the SimPoint estimate profile) reads minstret = the
458	// plugin-side retire counter (N_total); pc=0 is the positive marker that
459	// the atexit path drained (no trigger). If any other trigger already
460	// drained, return immediately (drained_already guards against double
461	// drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4; use
462	// _exit() to skip the rest of the atexit chain.
463	static void on_atexit(qemu_plugin_id_t id, void *udata)
464	{
465	    (void) id;
466	    (void) udata;
467	    if (drained_already) return;
468	    if (!drain_at_exit_mode) return;
469	    struct hybrid_state_v1 s = {0};
470	    s.magic    = HYBRID_STATE_MAGIC;
471	    s.version  = HYBRID_STATE_VERSION;
472	    s.flags    = HYBRID_FLAG_RV64;
473	    s.priv     = 3;
474	    s.minstret = atexit_insn_count;
475	    if (write_state_atomic(&s, outfile_path) != 0)
476	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
477	    else
478	        fprintf(stderr,
479	                "hybrid_handoff: drained exit count record to %s "
480	                "(minstret=%" PRIu64 ")\n",
481	                outfile_path, s.minstret);
482	    fflush(stderr);
483	    _exit(200);
484	}
485	
486	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
487	// When armed (the exit boundary's own tick ran), this tick fires before its
488	// insn executes, so a drain here records the post-retire state of the
489	// boundary insn with pc = the dynamically-next insn's vaddr.
490	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
491	{
492	    const HandoffSite *site = (const HandoffSite *) udata;
493	    if (oracle_armed
494	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
495	        handoff_drain(vcpu_idx, site->vaddr);
496	    }
497	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
498	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
499	        oracle_armed = 1;
500	    }
501	}
502	
503	// Checkpoint drain for cosim mode: write <outfile>.ckpt<k> and KEEP RUNNING
504	// (no exit, drained_already untouched -- the final count uses handoff_drain).
505	static void cosim_checkpoint_drain(unsigned int vcpu_idx, uint64_t pc,
506	                                   size_t k)
507	{
508	    g_autofree char *path = g_strdup_printf("%s.ckpt%zu", outfile_path, k);
509	    drain_state_to_file(vcpu_idx, pc, 0, path);
510	}
511	
512	// Per-insn tick for cosim mode. udata is this insn's HandoffSite. Exec
513	// callbacks fire pre-execution: at an armed tick, `cosim_done` post-entry
514	// insns have retired and the current insn has not, so draining when
515	// cosim_done == target captures "entry + target retires" with pc = the
516	// dynamically-next insn's vaddr -- the same point as the vsim checkpoint's
517	// DPC at minstret delta == target.
518	static void on_cosim_tick(unsigned int vcpu_idx, void *udata)
519	{
520	    const HandoffSite *site = (const HandoffSite *) udata;
521	    if (!cosim_armed) {
522	        if (cosim_pc_mode ? (site->vaddr == cosim_pc_arg)
523	                          : (site->kind == HYBRID_HANDOFF_ENTER)) {
524	            cosim_armed = 1;
525	            // Marker mode: the marker is counted by neither side -- done.
526	            // pc mode: the boundary insn retires inside the window (the
527	            // handoff resumes AT it) -- fall through and count this tick.
528	            if (!cosim_pc_mode) return;
529	        } else {
530	            return;
531	        }
532	    }
533	    if (cosim_idx < cosim_n_counts && cosim_done == cosim_counts[cosim_idx]) {
534	        if (cosim_idx + 1 == cosim_n_counts)
535	            handoff_drain(vcpu_idx, site->vaddr);  // final: exits 200
536	        else
537	            cosim_checkpoint_drain(vcpu_idx, site->vaddr, cosim_idx + 1);
538	        cosim_idx++;
539	    }
540	    cosim_done++;
541	}
542	
543	// Per-insn tick for icount mode. udata is the per-insn HandoffSite
544	// pre-allocated at translation time, so on_handoff's compute_handoff_pc
545	// returns the lag-free post-trigger PC (same property as the CSR path).
546	static void on_icount_tick(unsigned int vcpu_idx, void *udata)
547	{
548	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
549	    if (++v->icount_retired < icount_target) return;
550	    on_handoff_boundary(vcpu_idx, udata);
551	}
552	
553	// Per-insn tick for BBV-emit mode. udata is the bb_id (1-based) cast to
554	// pointer; that mapping is stable across calls because bbv_emit_assign_id
555	// is hashed by TB-start PC. The tick attributes one insn to the bb_id and
556	// flushes a slice row when the per-slice counter saturates.
557	static void on_bbv_tick(unsigned int vcpu_idx, void *udata)
558	{
559	    (void) vcpu_idx;
560	    uint64_t bb_id = (uint64_t) GPOINTER_TO_UINT(udata);
561	    bbv_emit_tick(bbv_emit, bb_id);
562	}
563	
564	// Per-insn tick for slice-consume mode (F11). Counts insns into the
565	// slice accumulator; on each slice boundary increments slice_consume_idx
566	// and resets the accumulator. Once slice_consume_idx exceeds the target
567	// slice index, drains via on_handoff at that same insn boundary. udata
568	// is the per-insn HandoffSite (allocated at translation time) so the
569	// post-trigger PC reaches on_handoff lag-free.
570	static void on_slice_consume_tick(unsigned int vcpu_idx, void *udata)
571	{
572	    if (++slice_consume_acc < bbv_slice_target) return;
573	    slice_consume_acc = 0;
574	    if (slice_consume_idx++ < slice_at_target) return;
575	    // After the post-increment above, slice_consume_idx == slice_at_target+1
576	    // (the count of fully retired slices). Log so the e2e test can verify
577	    // drain timing without relying on minstret (which is a cycle-counter
578	    // proxy on andes-ax45mpv and does not track plugin-counted insns).
579	    fprintf(stderr,
580	            "hybrid_handoff: slice-consume drain (idx=%" PRIu64
581	            " target=%" PRIu64 ")\n",
582	            slice_consume_idx, slice_at_target);
583	    on_handoff_boundary(vcpu_idx, udata);
584	}
585	
586	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
587	{
588	    (void) id;
589	    size_t n = qemu_plugin_tb_n_insns(tb);
590	
591	    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
592	    // TB-start vaddr). Same id is shared by every insn in the TB.
593	    uint64_t bb_id = 0;
594	    if (bbv_mode && n > 0) {
595	        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
596	        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
597	    }
598	
599	    for (size_t i = 0; i < n; i++) {
600	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
601	
602	        // Oracle exit-drain mode: exclusive with every other mode (enforced
603	        // at install), so it owns the insn's registration outright. The site
604	        // carries the marker kind so the tick can arm on the EXIT marker.
605	        if (exit_marker_mode || exit_pc_mode) {
606	            HandoffSite *site = g_new0(HandoffSite, 1);
607	            site->kind  = HYBRID_HANDOFF_NONE;
608	            site->vaddr = qemu_plugin_insn_vaddr(insn);
609	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
610	            if (exit_marker_mode && site->size == 4) {
611	                uint32_t raw = 0;
612	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
613	                    hybrid_match_handoff_insn(raw, &site->kind);
614	            }
615	            qemu_plugin_register_vcpu_insn_exec_cb(
616	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
617	            continue;
618	        }
619	
620	        // Cosim oracle mode: exclusive with every other mode (enforced at
621	        // install). Same site shape as the exit oracle; kind carries the
622	        // marker match so the tick can arm on the ENTER marker.
623	        if (cosim_marker_mode || cosim_pc_mode) {
624	            HandoffSite *site = g_new0(HandoffSite, 1);
625	            site->kind  = HYBRID_HANDOFF_NONE;
626	            site->vaddr = qemu_plugin_insn_vaddr(insn);
627	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
628	            if (cosim_marker_mode && site->size == 4) {
629	                uint32_t raw = 0;
630	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
631	                    hybrid_match_handoff_insn(raw, &site->kind);
632	            }
633	            qemu_plugin_register_vcpu_insn_exec_cb(
634	                insn, on_cosim_tick, QEMU_PLUGIN_CB_R_REGS, site);
635	            continue;
636	        }
637	
638	        // F14 count tick: registered FIRST so the count is incremented
639	        // before any trigger callback can call exit(200). NO_REGS keeps
640	        // the per-insn cost minimal (a single uint64 add).
641	        if (drain_at_exit_mode) {
642	            qemu_plugin_register_vcpu_insn_exec_cb(
643	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
644	        }
645	
646	        // BBV callback is registered BEFORE icount so that if both modes
647	        // fire on the same insn (icount target == slice multiple), the
648	        // slice row is emitted before exit(200) is called.
649	        if (bbv_mode) {
650	            qemu_plugin_register_vcpu_insn_exec_cb(
651	                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
652	                GUINT_TO_POINTER((guint) bb_id));
653	        }
654	
655	        // Slice-consume callback (F11). Registered after BBV so a BBV
656	        // row at the same boundary is flushed first; ordering vs icount
657	        // is irrelevant (both drain).
658	        if (slice_consume_mode) {
659	            HandoffSite *site = g_new0(HandoffSite, 1);
660	            site->kind  = HYBRID_HANDOFF_ENTER;
661	            site->vaddr = qemu_plugin_insn_vaddr(insn);
662	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
663	            qemu_plugin_register_vcpu_insn_exec_cb(
664	                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
665	        }
666	
667	        if (icount_mode) {
668	            HandoffSite *site = g_new0(HandoffSite, 1);
669	            site->kind  = HYBRID_HANDOFF_ENTER;
670	            site->vaddr = qemu_plugin_insn_vaddr(insn);
671	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
672	            qemu_plugin_register_vcpu_insn_exec_cb(
673	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
674	        }
675	
676	        if (pc_mode) {
677	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
678	            // boundary (on_handoff_boundary), so the insn size is recorded
679	            // only for completeness.
680	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
681	            HandoffSite *site = g_new0(HandoffSite, 1);
682	            site->kind  = HYBRID_HANDOFF_ENTER;
683	            site->vaddr = qemu_plugin_insn_vaddr(insn);
684	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
685	            qemu_plugin_register_vcpu_insn_exec_cb(
686	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
687	            continue;
688	        }
689	
690	        // Marker-trigger mode (default).
691	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
692	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
693	        // exact, not an approximation.
694	        size_t sz = qemu_plugin_insn_size(insn);
695	        if (sz != 4) continue;
696	        uint32_t raw = 0;
697	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
698	            continue;
699	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
700	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
701	        HandoffSite *site = g_new0(HandoffSite, 1);
702	        site->kind  = kind;
703	        site->vaddr = qemu_plugin_insn_vaddr(insn);
704	        site->size  = (uint32_t) sz;
705	        qemu_plugin_register_vcpu_insn_exec_cb(
706	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
707	    }
708	}
709	
710	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
711	                                           const qemu_info_t *info,
712	                                           int argc, char **argv)
713	{
714	    (void) info;
715	    for (int i = 0; i < argc; i++) {
716	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
717	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
718	            outfile_path = g_strdup(tok[1]);
719	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
720	            char *endp = NULL;
721	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
722	            if (!endp || *endp != '\0') {
723	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
724	                        tok[1]);
725	                return -1;
726	            }
727	            enter_pc_arg = (uint64_t) v;
728	            pc_mode = 1;
729	        } else if (g_strcmp0(tok[0], "icount") == 0 && tok[1]) {
730	            char *endp = NULL;
731	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
732	            if (!endp || *endp != '\0' || v == 0) {
733	                fprintf(stderr, "hybrid_handoff: invalid icount=%s\n",
734	                        tok[1]);
735	                return -1;
736	            }
737	            icount_target = (uint64_t) v;
738	            icount_mode = 1;
739	        } else if (g_strcmp0(tok[0], "bbv_out") == 0 && tok[1]) {
740	            bbv_out_path = g_strdup(tok[1]);
741	            bbv_mode = 1;
742	        } else if (g_strcmp0(tok[0], "slice") == 0 && tok[1]) {
743	            char *endp = NULL;
744	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
745	            if (!endp || *endp != '\0' || v == 0) {
746	                fprintf(stderr, "hybrid_handoff: invalid slice=%s\n",
747	                        tok[1]);
748	                return -1;
749	            }
750	            bbv_slice_target = (uint64_t) v;
751	        } else if (g_strcmp0(tok[0], "slice_at") == 0 && tok[1]) {
752	            char *endp = NULL;
753	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
754	            if (!endp || *endp != '\0') {
755	                fprintf(stderr, "hybrid_handoff: invalid slice_at=%s\n",
756	                        tok[1]);
757	                return -1;
758	            }
759	            slice_at_target = (uint64_t) v;
760	            slice_consume_mode = 1;
761	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
762	            char *endp = NULL;
763	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
764	            if (!endp || *endp != '\0') {
765	                fprintf(stderr, "hybrid_handoff: invalid exit_pc=%s\n",
766	                        tok[1]);
767	                return -1;
768	            }
769	            exit_pc_arg = (uint64_t) v;
770	            exit_pc_mode = 1;
771	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
772	            char *endp = NULL;
773	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
774	            if (!endp || *endp != '\0') {
775	                fprintf(stderr, "hybrid_handoff: invalid exit_marker=%s\n",
776	                        tok[1]);
777	                return -1;
778	            }
779	            exit_marker_mode = (v != 0);
780	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
781	            char *endp = NULL;
782	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
783	            if (!endp || *endp != '\0') {
784	                fprintf(stderr, "hybrid_handoff: invalid drain_pc=%s\n",
785	                        tok[1]);
786	                return -1;
787	            }
788	            drain_pc_arg = (uint64_t) v;
789	            drain_pc_set = 1;
790	        } else if (g_strcmp0(tok[0], "cosim_pc") == 0 && tok[1]) {
791	            char *endp = NULL;
792	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
793	            if (!endp || *endp != '\0') {
794	                fprintf(stderr, "hybrid_handoff: invalid cosim_pc=%s\n",
795	                        tok[1]);
796	                return -1;
797	            }
798	            cosim_pc_arg = (uint64_t) v;
799	            cosim_pc_mode = 1;
800	        } else if (g_strcmp0(tok[0], "cosim_marker") == 0 && tok[1]) {
801	            char *endp = NULL;
802	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
803	            if (!endp || *endp != '\0') {
804	                fprintf(stderr, "hybrid_handoff: invalid cosim_marker=%s\n",
805	                        tok[1]);
806	                return -1;
807	            }
808	            cosim_marker_mode = (v != 0);
809	        } else if (g_strcmp0(tok[0], "cosim_counts") == 0 && tok[1]) {
810	            g_auto(GStrv) parts = g_strsplit(tok[1], ":", -1);
811	            size_t n = g_strv_length(parts);
812	            if (n == 0) {
813	                fprintf(stderr, "hybrid_handoff: empty cosim_counts\n");
814	                return -1;
815	            }
816	            cosim_counts = g_new0(uint64_t, n);
817	            for (size_t k = 0; k < n; k++) {
818	                char *endp = NULL;
819	                unsigned long long v = g_ascii_strtoull(parts[k], &endp, 0);
820	                if (parts[k][0] == '\0' || !endp || *endp != '\0') {
821	                    fprintf(stderr,
822	                            "hybrid_handoff: invalid cosim_counts entry: %s\n",
823	                            parts[k]);
824	                    return -1;
825	                }
826	                if (k > 0 && v <= cosim_counts[k - 1]) {
827	                    fprintf(stderr, "hybrid_handoff: cosim_counts must be "
828	                                    "strictly ascending\n");
829	                    return -1;
830	                }
831	                cosim_counts[k] = (uint64_t) v;
832	            }
833	            cosim_n_counts = n;
834	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
835	            // F14: any non-zero value enables. "1" is the canonical form
836	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
837	            // also enable -- the flag is a binary switch, not a count.
838	            char *endp = NULL;
839	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
840	            if (!endp || *endp != '\0') {
841	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
842	                        tok[1]);
843	                return -1;
844	            }
845	            drain_at_exit_mode = (v != 0);
846	        } else {
847	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
848	            return -1;
849	        }
850	    }
851	    if (!outfile_path) {
852	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
853	        return -1;
854	    }
855	    if (pc_mode) {
856	        fprintf(stderr,
857	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
858	                enter_pc_arg);
859	    }
860	    if (icount_mode) {
861	        fprintf(stderr,
862	                "hybrid_handoff: icount-mode target=%" PRIu64 "\n",
863	                icount_target);
864	    }
865	    if (bbv_mode) {
866	        if (bbv_slice_target == 0) {
867	            fputs("hybrid_handoff: bbv_out= requires slice=N\n", stderr);
868	            return -1;
869	        }
870	        bbv_emit = bbv_emit_new(bbv_out_path, bbv_slice_target);
871	        if (!bbv_emit) {
872	            fprintf(stderr, "hybrid_handoff: failed to open bbv_out=%s\n",
873	                    bbv_out_path);
874	            return -1;
875	        }
876	        fprintf(stderr,
877	                "hybrid_handoff: bbv-mode out=%s slice=%" PRIu64 "\n",
878	                bbv_out_path, bbv_slice_target);
879	    }
880	    if (slice_consume_mode) {
881	        if (bbv_slice_target == 0) {
882	            fputs("hybrid_handoff: slice_at= requires slice=N\n", stderr);
883	            return -1;
884	        }
885	        fprintf(stderr,
886	                "hybrid_handoff: slice-consume mode slice=%" PRIu64
887	                " slice_at=%" PRIu64 "\n",
888	                bbv_slice_target, slice_at_target);
889	    }
890	    if (drain_at_exit_mode) {
891	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
892	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
893	    }
894	    if (exit_marker_mode || exit_pc_mode) {
895	        if ((exit_marker_mode && exit_pc_mode) || pc_mode || icount_mode
896	            || bbv_mode || slice_consume_mode || drain_at_exit_mode
897	            || cosim_marker_mode || cosim_pc_mode) {
898	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
899	                  "is exclusive with the other trigger modes\n", stderr);
900	            return -1;
901	        }
902	        if (exit_pc_mode) {
903	            fprintf(stderr,
904	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
905	                    PRIx64 "\n", exit_pc_arg);
906	        } else {
907	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
908	                  stderr);
909	        }
910	        if (drain_pc_set) {
911	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
912	                    drain_pc_arg);
913	        }
914	    } else if (drain_pc_set) {
915	        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
916	              "(exit_marker/exit_pc)\n", stderr);
917	        return -1;
918	    }
919	    if (cosim_marker_mode || cosim_pc_mode) {
920	        if ((cosim_marker_mode && cosim_pc_mode) || pc_mode || icount_mode
921	            || bbv_mode || slice_consume_mode || drain_at_exit_mode) {
922	            fputs("hybrid_handoff: cosim mode (cosim_marker/cosim_pc) is "
923	                  "exclusive with the other trigger modes\n", stderr);
924	            return -1;
925	        }
926	        if (cosim_n_counts == 0) {
927	            fputs("hybrid_handoff: cosim mode requires cosim_counts=a:b:...\n",
928	                  stderr);
929	            return -1;
930	        }
931	        if (cosim_pc_mode) {
932	            fprintf(stderr,
933	                    "hybrid_handoff: cosim mode entry pc=0x%" PRIx64
934	                    ", %zu drain count(s)\n", cosim_pc_arg, cosim_n_counts);
935	        } else {
936	            fprintf(stderr,
937	                    "hybrid_handoff: cosim mode (entry marker), "
938	                    "%zu drain count(s)\n", cosim_n_counts);
939	        }
940	    } else if (cosim_n_counts != 0) {
941	        fputs("hybrid_handoff: cosim_counts requires cosim mode "
942	              "(cosim_marker/cosim_pc)\n", stderr);
943	        return -1;
944	    }
945	
946	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
947	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
948	    return 0;
949	}
