1	// ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
2	// ops against the RISC-V Debug Module. The orchestration is testable in
3	// isolation by injecting a recording bus.
4	
5	#include "hybrid/abstract_command.hpp"
6	#include "hybrid/program_buffer.hpp"
7	#include "hybrid/resume_driver.hpp"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_regfile_xfer.hpp"
10	
11	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
12	#include <doctest.h>
13	
14	#include <cstdint>
15	#include <deque>
16	#include <optional>
17	#include <vector>
18	
19	namespace {
20	
21	// DMI register addresses from RISC-V Debug Spec 1.0.
22	constexpr uint8_t kDmcontrol  = 0x10;
23	constexpr uint8_t kDmstatus   = 0x11;
24	constexpr uint8_t kAbstractcs = 0x16;
25	constexpr uint8_t kCommand    = 0x17;
26	constexpr uint8_t kData0      = 0x04;
27	constexpr uint8_t kData1      = 0x05;
28	
29	// CSR numbers from Debug Spec.
30	constexpr uint16_t kCsrDpc  = 0x7B1;
31	constexpr uint16_t kCsrDcsr = 0x7B0;
32	
33	struct DmiOp
34	{
35	  enum class Kind
36	  {
37	    Write,
38	    Read,
39	  };
40	  Kind kind;
41	  uint8_t reg;
42	  uint32_t value;  // for writes only
43	};
44	
45	struct RecordingBus final : hybrid::DmiBus
46	{
47	  std::vector<DmiOp> ops;
48	
49	  // Test-controlled response values for reads.
50	  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
51	  uint32_t abstractcs_value = 0;     // fallback when queue is empty
52	  std::deque<uint32_t> abstractcs_queue; // queued reads drain first
53	
54	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
55	  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
56	  // fallback). Models real hardware and -- unlike positional queueing -- is
57	  // robust to however many unrelated abstract ops precede the targeted write.
58	  std::optional<uint16_t> fail_csr_write;
59	
60	  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
61	  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
62	  // re-arms to false after firing - tests can flip it back on to fail a
63	  // later PB exec.
64	  bool fail_next_pb_exec = false;
65	
66	  void write(uint8_t reg, uint32_t value) override
67	  {
68	    ops.push_back({DmiOp::Kind::Write, reg, value});
69	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
70	      cmderr_sticky_ = false;  // W1C clear
71	    if (reg == kCommand && fail_csr_write) {
72	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
73	      const bool is_write = ((value >> 16) & 1u) != 0u;
74	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
75	        cmderr_sticky_ = true;
76	    }
77	    if (reg == kCommand && value == hybrid::kExecProgbufCmd
78	        && fail_next_pb_exec) {
79	      cmderr_sticky_ = true;
80	      fail_next_pb_exec = false;
81	    }
82	  }
83	
84	  auto read(uint8_t reg) -> uint32_t override
85	  {
86	    ops.push_back({DmiOp::Kind::Read, reg, 0});
87	    if (reg == kDmstatus) return dmstatus_value;
88	    if (reg == kAbstractcs) {
89	      if (cmderr_sticky_) return kCmderrMask;
90	      if (!abstractcs_queue.empty()) {
91	        auto v = abstractcs_queue.front();
92	        abstractcs_queue.pop_front();
93	        return v;
94	      }
95	      return abstractcs_value;
96	    }
97	    return 0;
98	  }
99	
100	private:
101	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
102	  bool cmderr_sticky_ = false;
103	};
104	
105	auto rv64_state(uint64_t pc, uint64_t x10) -> hybrid_state_v1
106	{
107	  hybrid_state_v1 s{};
108	  s.magic = HYBRID_STATE_MAGIC;
109	  s.version = HYBRID_STATE_VERSION;
110	  s.flags = HYBRID_FLAG_RV64;
111	  s.pc = pc;
112	  s.priv = 3;
113	  s.gpr[10] = x10;
114	  return s;
115	}
116	
117	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
118	  -> std::vector<uint32_t>
119	{
120	  std::vector<uint32_t> values;
121	  for (const auto& op : ops)
122	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
123	      values.push_back(op.value);
124	  return values;
125	}
126	
127	auto count_writes_to(const std::vector<DmiOp>& ops, uint8_t reg) -> std::size_t
128	{
129	  std::size_t n = 0;
130	  for (const auto& op : ops)
131	    if (op.kind == DmiOp::Kind::Write && op.reg == reg) ++n;
132	  return n;
133	}
134	
135	}  // namespace
136	
137	TEST_CASE("resume halts the hart before any abstract command")
138	{
139	  RecordingBus bus;
140	  // dmstatus answers halted+resumeack so poll loops finish on the first read.
141	  bus.dmstatus_value = (1u << 9) | (1u << 17);
142	
143	  hybrid::ResumeDriver driver(bus);
144	  driver.resume(rv64_state(/*pc=*/0x80001000, /*x10=*/0xdeadbeef));
145	
146	  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
147	  // accepted; the second write must add haltreq while keeping dmactive set.
148	  REQUIRE(bus.ops.size() >= 2);
149	
150	  const auto& prime = bus.ops[0];
151	  CHECK(prime.kind == DmiOp::Kind::Write);
152	  CHECK(prime.reg == kDmcontrol);
153	  CHECK((prime.value & 1u) == 1u);                  // dmactive
154	  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set
155	
156	  const auto& halt = bus.ops[1];
157	  CHECK(halt.kind == DmiOp::Kind::Write);
158	  CHECK(halt.reg == kDmcontrol);
159	  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
160	  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
161	}
162	
163	TEST_CASE("resume programs x1..x31 via DATA0/DATA1 + COMMAND, skipping x0")
164	{
165	  RecordingBus bus;
166	  bus.dmstatus_value = (1u << 9) | (1u << 17);
167	
168	  auto s = rv64_state(0x80001000, 0xdeadbeef);
169	  for (int i = 0; i < 32; ++i) s.gpr[i] = 0xa00000000ULL + i;
170	
171	  hybrid::ResumeDriver driver(bus);
172	  driver.resume(s);
173	
174	  std::vector<uint32_t> cmds;
175	  for (const auto& op : bus.ops)
176	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
177	      cmds.push_back(op.value);
178	
179	  CHECK(cmds.size() >= 31);
180	
181	  for (int i = 1; i < 32; ++i) {
182	    const auto expect =
183	      hybrid::access_register_command(hybrid::regno_gpr(i),
184	                                      hybrid::AarSize::Bits64, /*write=*/true);
185	    CHECK(cmds[i - 1] == expect);
186	  }
187	
188	  for (const auto& cmd : cmds) {
189	    const uint16_t regno = cmd & 0xffffu;
190	    CHECK(regno != hybrid::regno_gpr(0));
191	  }
192	}
193	
194	TEST_CASE("resume writes DPC = state.pc")
195	{
196	  RecordingBus bus;
197	  bus.dmstatus_value = (1u << 9) | (1u << 17);
198	
199	  constexpr uint64_t pc = 0x12345678'9ABCDEF0ULL;
200	  hybrid::ResumeDriver driver(bus);
201	  driver.resume(rv64_state(pc, 0));
202	
203	  // Look for the COMMAND write that targets CSR DPC (regno=0x7B1).
204	  std::vector<std::size_t> dpc_cmd_indices;
205	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
206	    const auto& op = bus.ops[i];
207	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
208	        && (op.value & 0xffffu) == kCsrDpc) {
209	      dpc_cmd_indices.push_back(i);
210	    }
211	  }
212	  REQUIRE(dpc_cmd_indices.size() == 1);
213	
214	  // Immediately preceding writes must set DATA0=low32(pc), DATA1=high32(pc).
215	  const auto cmd_idx = dpc_cmd_indices[0];
216	  REQUIRE(cmd_idx >= 2);
217	  const auto& d0 = bus.ops[cmd_idx - 2];
